-- Comentarios do CTN, lote 2 (arts. 21 a 40). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 21 and 40 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(21,'','Imposto de importação: alteração de alíquotas e bases pelo Executivo','O Poder Executivo pode, nas condições e nos limites estabelecidos em lei, alterar as alíquotas ou as bases de cálculo do imposto, a fim de ajustá-lo aos objetivos da política cambial e do comércio exterior.'),
(22,'','Imposto de importação: contribuinte','Contribuinte do imposto é o importador ou quem a lei a ele equiparar (inciso I) e o arrematante de produtos apreendidos ou abandonados (inciso II).'),
(23,'','Imposto de exportação: fato gerador','O imposto, de competência da União, sobre a exportação, para o estrangeiro, de produtos nacionais ou nacionalizados tem como fato gerador a saída destes do território nacional.'),
(24,'','Imposto de exportação: base de cálculo','A base de cálculo do imposto é, quando a alíquota seja específica, a unidade de medida adotada pela lei tributária (inciso I) e, quando a alíquota seja ad valorem, o preço normal que o produto, ou seu similar, alcançaria, ao tempo da exportação, em uma venda em condições de livre concorrência (inciso II). O parágrafo único dispõe que, para os efeitos do inciso II, considera-se a entrega como efetuada no porto ou lugar da saída do produto, deduzidos os tributos diretamente incidentes sobre a operação de exportação e, nas vendas a prazo superior aos correntes no mercado internacional, o custo do financiamento.'),
(25,'','Imposto de exportação: base de cálculo por parcela excedente','A lei pode adotar como base de cálculo a parcela do valor ou do preço, referidos no artigo anterior, excedente de valor básico, fixado de acordo com os critérios e dentro dos limites por ela estabelecidos.'),
(26,'','Imposto de exportação: alteração de alíquotas e bases pelo Executivo','O Poder Executivo pode, nas condições e nos limites estabelecidos em lei, alterar as alíquotas ou as bases de cálculo do imposto, a fim de ajustá-los aos objetivos da política cambial e do comércio exterior.'),
(27,'','Imposto de exportação: contribuinte','Contribuinte do imposto é o exportador ou quem a lei a ele equiparar.'),
(28,'','Imposto de exportação: destinação da receita','A receita líquida do imposto destina-se à formação de reservas monetárias, na forma da lei.'),
(29,'','ITR: fato gerador','O imposto, de competência da União, sobre a propriedade territorial rural tem como fato gerador a propriedade, o domínio útil ou a posse de imóvel por natureza, como definido na lei civil, localizado fora da zona urbana do Município.'),
(30,'','ITR: base de cálculo','A base do cálculo do imposto é o valor fundiário.'),
(31,'','ITR: contribuinte','Contribuinte do imposto é o proprietário do imóvel, o titular de seu domínio útil, ou o seu possuidor a qualquer título.'),
(32,'','IPTU: fato gerador e zona urbana','O imposto, de competência dos Municípios, sobre a propriedade predial e territorial urbana tem como fato gerador a propriedade, o domínio útil ou a posse de bem imóvel por natureza ou por acessão física, como definido na lei civil, localizado na zona urbana do Município. O § 1º entende como zona urbana a definida em lei municipal, observado o requisito mínimo da existência de melhoramentos indicados em pelo menos 2 (dois) dos incisos seguintes, construídos ou mantidos pelo Poder Público: meio-fio ou calçamento com canalização de águas pluviais (I); abastecimento de água (II); sistema de esgotos sanitários (III); rede de iluminação pública, com ou sem posteamento para distribuição domiciliar (IV); e escola primária ou posto de saúde a uma distância máxima de 3 (três) quilômetros do imóvel considerado (V). O § 2º dispõe que a lei municipal pode considerar urbanas as áreas urbanizáveis, ou de expansão urbana, constantes de loteamentos aprovados pelos órgãos competentes, destinados à habitação, à indústria ou ao comércio, mesmo que localizados fora das zonas definidas nos termos do parágrafo anterior.'),
(33,'','IPTU: base de cálculo','A base do cálculo do imposto é o valor venal do imóvel. O parágrafo único dispõe que, na determinação da base de cálculo, não se considera o valor dos bens móveis mantidos, em caráter permanente ou temporário, no imóvel, para efeito de sua utilização, exploração, aformoseamento ou comodidade.'),
(34,'','IPTU: contribuinte','Contribuinte do imposto é o proprietário do imóvel, o titular do seu domínio útil, ou o seu possuidor a qualquer título.'),
(35,'','ITBI: fato gerador','O Imposto sobre a Transmissão Inter vivos, por Ato Oneroso, de Bens Imóveis e de Direitos a Eles Relativos, de competência dos Municípios e do Distrito Federal, tem como fato gerador, na redação dada pela Lei Complementar n. 227, de 2026: a transmissão inter vivos, a qualquer título, por ato oneroso, da propriedade ou do domínio útil de bens imóveis por natureza ou por acessão física, como definidos na lei civil (inciso I); a transmissão inter vivos, a qualquer título, por ato oneroso, de direitos reais sobre imóveis, exceto os direitos reais de garantia (inciso II); e a cessão inter vivos, por ato oneroso, de direitos relativos às transmissões referidas nos incisos I e II (inciso III).'),
(36,'','ITBI: hipóteses de não incidência','Ressalvado o disposto no artigo seguinte, o imposto não incide sobre a transmissão dos bens ou direitos referidos no artigo anterior quando efetuada para sua incorporação ao patrimônio de pessoa jurídica em pagamento de capital nela subscrito (inciso I) e quando decorrente da incorporação ou da fusão de uma pessoa jurídica por outra ou com outra (inciso II). O parágrafo único dispõe que o imposto não incide sobre a transmissão aos mesmos alienantes, dos bens e direitos adquiridos na forma do inciso I, em decorrência da sua desincorporação do patrimônio da pessoa jurídica a que foram conferidos.'),
(37,'','ITBI: atividade preponderante imobiliária','O disposto no artigo anterior não se aplica quando a pessoa jurídica adquirente tenha como atividade preponderante a venda ou locação de propriedade imobiliária ou a cessão de direitos relativos à sua aquisição. O § 1º considera caracterizada a atividade preponderante quando mais de 50% da receita operacional da adquirente, nos 2 anos anteriores e nos 2 anos subsequentes à aquisição, decorrer dessas transações. O § 2º dispõe que, se a adquirente iniciar suas atividades após a aquisição, ou menos de 2 anos antes dela, a preponderância é apurada levando em conta os 3 primeiros anos seguintes à data da aquisição. O § 3º dispõe que, verificada a preponderância, torna-se devido o imposto, nos termos da lei vigente à data da aquisição, sobre o valor do bem ou direito nessa data. O § 4º dispõe que o artigo não se aplica à transmissão de bens ou direitos realizada em conjunto com a da totalidade do patrimônio da pessoa jurídica alienante.'),
(38,'','ITBI: base de cálculo e valor venal','A base de cálculo do imposto é o valor venal dos bens ou direitos transmitidos. O § 1º, incluído pela Lei Complementar n. 227, de 2026, considera valor venal o valor pelo qual o bem ou direito seria negociado à vista, em condições normais de mercado. O § 2º dispõe que esse valor será estimado por critérios técnicos, considerando pelo menos um de: análise de preços praticados no mercado imobiliário (I); informações prestadas pelos serviços notariais e registrais e por agentes financeiros (II); localização, tipologia, destinação, padrão e área de terreno e construção, entre outras características do bem imóvel (III); e outros parâmetros técnicos usualmente observados na avaliação de imóveis (IV). O § 3º trata da divulgação, pelas administrações tributárias dos Municípios e do Distrito Federal, dos critérios usados para estimar o valor venal, que poderá ser contestado pelo contribuinte mediante avaliação contraditória em procedimento específico, nos termos do parágrafo. O § 4º dispõe que os serviços registrais e notariais deverão compartilhar as informações das operações com bens imóveis com as administrações tributárias dos Municípios e do Distrito Federal, sob pena de multa prevista em lei específica municipal ou distrital.'),
(40,'','ITBI: dedução do montante no imposto de renda','O montante do imposto é dedutível do devido à União, a título do imposto de que trata o art. 43, sobre o provento decorrente da mesma transmissão.')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
